-- ==============================================================================
-- SCHEMA & DATA CHO SUPABASE (POSTGRESQL) - DỰ ÁN CONGEARS
-- Chạy toàn bộ script này trong: Supabase Dashboard -> SQL Editor -> New Query -> Run
-- ==============================================================================

-- 1. TẠO BẢNG LAPTOPS
CREATE TABLE IF NOT EXISTS public.laptops (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL,
    slug TEXT UNIQUE NOT NULL,
    category TEXT NOT NULL CHECK (category IN ('gaming', 'office')),
    brand TEXT NOT NULL,
    series TEXT NOT NULL,
    cpu TEXT NOT NULL,
    gpu TEXT NOT NULL,
    ram TEXT NOT NULL,
    storage TEXT NOT NULL,
    screen TEXT NOT NULL,
    weight TEXT,
    price NUMERIC(15, 2) NOT NULL,
    old_price NUMERIC(15, 2) NOT NULL,
    highlight TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Bật RLS (Row Level Security) và cho phép đọc public
ALTER TABLE public.laptops ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Cho phép đọc công khai danh sách laptop"
ON public.laptops
FOR SELECT
TO anon, authenticated
USING (true);

-- 2. DỮ LIỆU 12 LAPTOP GAMING
ON CONFLICT (slug) DO NOTHING;

-- 3. DỮ LIỆU 20 LAPTOP VĂN PHÒNG
ON CONFLICT (slug) DO NOTHING;
